// Installing dotmd's integration into agent hosts other than Claude Code.
//
// Claude Code gets its integration through a real plugin (`plugins/dotmd/`,
// installed by `claude plugin`). OpenCode has no equivalent registry, but it
// auto-discovers plugin files: it globs `{plugin,plugins}/*.{ts,js}` under the
// global config dir and under a project's `.opencode/`, with no config entry
// needed. So the integration ships as one generated file.
//
// It goes in the GLOBAL config dir, not per-repo. dotmd retired per-repo
// generated scaffolding once already (`.claude/commands`, see
// claude-commands.mjs) because a file copied into every repo drifts from the
// CLI that wrote it. One global file covers every repo and is refreshed by
// `dotmd update` in lockstep with the CLI.
//
// Writing outside the repo is why this is an explicit verb. `dotmd doctor`
// reports that the integration is missing and names the command; it never
// installs. Passive commands touch nothing.

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { hostSessionSource } from './util.mjs';
import { readEnv, stateDir } from './naming.mjs';

export const GENERATED_MARKER = 'dotmd-generated:';
const PLUGIN_FILENAME = 'dotmd.js';
const ASSET = path.resolve(fileURLToPath(import.meta.url), '..', '..', 'assets', 'opencode', 'plugin.js');

// OpenCode's own resolution order for its global config directory. Verified
// against the shipped binary: `OPENCODE_CONFIG_DIR` is an explicit override it
// consults directly, and the default is the XDG location.
export function opencodeConfigDir(env = process.env, homedir = os.homedir()) {
  const explicit = env.OPENCODE_CONFIG_DIR?.trim();
  if (explicit) return path.resolve(explicit);
  const xdg = env.XDG_CONFIG_HOME?.trim();
  return xdg ? path.join(path.resolve(xdg), 'opencode') : path.join(homedir, '.config', 'opencode');
}

// Both spellings are globbed, so an existing one is adopted rather than
// creating a second plugin directory beside the user's own plugins.
export function opencodePluginDir(configDir) {
  for (const name of ['plugin', 'plugins']) {
    const candidate = path.join(configDir, name);
    if (existsSync(candidate)) return candidate;
  }
  return path.join(configDir, 'plugin');
}

export function opencodePluginPath(opts = {}) {
  const { env = process.env, homedir = os.homedir(), dir } = opts;
  if (dir) return path.join(path.resolve(dir), PLUGIN_FILENAME);
  return path.join(opencodePluginDir(opencodeConfigDir(env, homedir)), PLUGIN_FILENAME);
}

function banner(version) {
  return [
    `// ${GENERATED_MARKER}${version}`,
    '// Generated by `dotmd install opencode`. Refreshed by `dotmd update`.',
    '// Hand edits are overwritten — remove with `dotmd install opencode --remove`.',
    '',
  ].join('\n');
}

export function renderOpencodePlugin(version) {
  return banner(version) + readFileSync(ASSET, 'utf8');
}

// The version a generated file was written by, or null when the file is absent
// or carries no dotmd banner. A file without the banner is the user's own and
// is never written or removed — same rule the retired slash-command scaffolding
// followed.
export function installedVersion(filePath) {
  let contents;
  try { contents = readFileSync(filePath, 'utf8'); } catch { return null; }
  const marker = contents.indexOf(GENERATED_MARKER);
  if (marker < 0) return null;
  const rest = contents.slice(marker + GENERATED_MARKER.length);
  return rest.split('\n', 1)[0].trim() || null;
}

export function opencodeStatus(opts = {}) {
  const { version, ...rest } = opts;
  const filePath = opencodePluginPath(rest);
  const exists = existsSync(filePath);
  const installed = exists ? installedVersion(filePath) : null;
  return {
    path: filePath,
    exists,
    version: installed,
    // Present but unmarked: the user put a `dotmd.js` there themselves.
    foreign: exists && installed === null,
    stale: installed !== null && version !== undefined && installed !== version,
  };
}

// Is OpenCode plausibly in use on this machine? Used only to decide whether to
// mention the integration — never to install anything.
export function opencodeDetected(opts = {}) {
  const { env = process.env, homedir = os.homedir() } = opts;
  if (env.OPENCODE || env.OPENCODE_PID) return true;
  const configDir = opencodeConfigDir(env, homedir);
  if (!existsSync(configDir)) return false;
  try { return readdirSync(configDir).length > 0; } catch { return false; }
}

export function installOpencodePlugin(opts = {}) {
  const { version, dryRun = false, force = false, ...rest } = opts;
  const status = opencodeStatus({ version, ...rest });
  if (status.foreign && !force) {
    return { ...status, action: 'refused', reason: 'a dotmd.js without a dotmd banner is already there — it was not written by dotmd' };
  }
  if (status.exists && !status.stale && !status.foreign) {
    return { ...status, action: 'current' };
  }
  const action = status.exists ? 'updated' : 'installed';
  if (!dryRun) {
    mkdirSync(path.dirname(status.path), { recursive: true });
    writeFileSync(status.path, renderOpencodePlugin(version), 'utf8');
  }
  return { ...status, action, version };
}

// What identity does dotmd actually see here, and can it tell this session
// apart from its siblings? This report exists because the OpenCode breakage was
// invisible until a verb failed: dotmd looked for variables OpenCode never set,
// and nothing surfaced that until `use` refused to run. Anyone on any host can
// now check what dotmd resolved instead of discovering it through a failure.
export function describeSessionIdentity(opts = {}) {
  const { env = process.env, homedir = os.homedir(), version } = opts;
  const source = hostSessionSource(env);
  const opencode = opencodeStatus({ env, homedir, version });
  const underOpencode = Boolean(env.OPENCODE || env.OPENCODE_PID);

  if (!source) {
    return {
      id: null, scope: 'none', source: null, host: null,
      summary: 'no session identity — `use`, `set`, `baton` and `archive` fail closed',
      advice: underOpencode
        ? ['runlist install opencode', 'or set RUNLIST_SESSION_ID for this shell']
        : ['set RUNLIST_SESSION_ID for this shell or host session', 'known hosts: runlist install'],
    };
  }

  const advice = [];
  // The distinction that matters: a process- or terminal-scoped id is shared by
  // every session under it, so those sessions can release each other's plans.
  if (source.scope === 'process' && source.host === 'OpenCode') {
    advice.push(opencode.exists
      // The plugin is there but this shell was spawned before it loaded, so it
      // still carries the old identity — say so rather than leave a warning
      // marker with no explanation.
      ? 'restart OpenCode — this session predates the installed integration'
      : 'dotmd install opencode  — for a per-session identity');
  } else if (source.scope === 'terminal') {
    advice.push('every agent session in this terminal shares this id — set RUNLIST_SESSION_ID per session');
  }
  return {
    id: source.id,
    scope: source.scope,
    source: source.variable,
    host: source.host,
    summary: source.scope === 'session'
      ? `per-session identity from ${source.variable}`
      : `${source.scope}-scoped identity from ${source.variable} — sessions sharing it can release each other's plans`,
    advice,
  };
}

// --- Telling the session it is running degraded -----------------------------
//
// Every other surface here has to be sought out: `doctor`, `install`, the npm
// postinstall line. But the degraded mode is SILENT — with the OPENCODE_PID
// fallback in place, `use`/`set`/`baton` all work, they just share one identity
// across every session in the OpenCode process. Nobody goes looking for a
// diagnostic about a thing that appears to work, so this comes to them.
//
// Warning, not error. Failing closed would undo the fallback that unblocked
// OpenCode in the first place, and punish a setup that is working.
//
// Once per session per repo, via a marker under the gitignored .dotmd/. Silent
// under RUNLIST_NO_HINTS=1, the switch the repeat-failure hints already use.
const NOTICE_DIR = 'notices';

function noticeMarkerPath(repoRoot, key) {
  const digest = createHash('sha256').update(key).digest('hex').slice(0, 32);
  return path.join(stateDir(repoRoot), NOTICE_DIR, `${digest}`);
}

// Returns the notice text the first time it applies in a session, then null.
// `record: false` answers without consuming the once-per-session budget.
export function degradedIdentityNotice(repoRoot, opts = {}) {
  const { env = process.env, homedir = os.homedir(), version, record = true } = opts;
  if (readEnv('NO_HINTS', env) === '1') return null;
  // Cheap env check first: a user on any other host pays nothing for this.
  if (!env.OPENCODE && !env.OPENCODE_PID) return null;

  const identity = describeSessionIdentity({ env, homedir, version });
  if (identity.scope === 'session') return null;

  const installed = opencodeStatus({ env, homedir, version }).exists;
  const lines = installed
    ? ['[dotmd] This OpenCode session started before the dotmd integration loaded, so its plan',
      '        ownership is still process-scoped. Restart OpenCode to pick it up.']
    : ['[dotmd] OpenCode detected, dotmd integration not installed — plan ownership is scoped to',
      '        the OpenCode process, so another session in it can release plans this one claimed,',
      '        and no session-start briefing runs. Fix once: dotmd install opencode'];

  if (!record) return lines.join('\n');
  if (!repoRoot) return lines.join('\n');
  const marker = noticeMarkerPath(repoRoot, `opencode:${identity.id}:${installed ? 'restart' : 'install'}`);
  if (existsSync(marker)) return null;
  try {
    mkdirSync(path.dirname(marker), { recursive: true });
    writeFileSync(marker, '', 'utf8');
  } catch {
    // Unwritable .dotmd: say it once anyway rather than stay silent about a
    // real ownership weakness. Worst case it repeats.
  }
  return lines.join('\n');
}

// --- Claude Code -----------------------------------------------------------
//
// Claude Code has a real plugin registry, so dotmd drives `claude plugin`
// rather than writing files. What it lacked was any CLI path to the FIRST
// install: `dotmd update` deliberately skips the plugin step when nothing is
// installed ("dotmd plugin not installed"), and the README's two slash commands
// only work from inside a session. So a user who installed the CLI from npm had
// no way to discover, from the CLI, that the plugin exists.

export const CLAUDE_MARKETPLACE = 'reowens/dotmd';
export const CLAUDE_PLUGIN_ID = 'dotmd@dotmd';

// Pure planner, mirroring planUpdate: the orchestration is unit-testable and
// the side effects stay in the caller.
export function planClaudeInstall({ installed, hasClaude, remove = false } = {}) {
  if (remove) {
    if (!installed) return [{ kind: 'skip', reason: 'dotmd plugin is not installed' }];
    return hasClaude
      ? [{ kind: 'run', cmd: ['claude', 'plugin', 'uninstall', installed.id] }]
      : [{ kind: 'manual', lines: [`/plugin uninstall ${installed.id}`] }];
  }
  if (installed) return [{ kind: 'skip', reason: `dotmd plugin already installed (${installed.version ?? 'unknown version'})` }];
  // The marketplace has to be registered before the plugin resolves; adding one
  // already present is a no-op, so this stays safe to re-run.
  if (!hasClaude) {
    return [{ kind: 'manual', lines: [`/plugin marketplace add ${CLAUDE_MARKETPLACE}`, `/plugin install ${CLAUDE_PLUGIN_ID}`] }];
  }
  return [
    { kind: 'run', cmd: ['claude', 'plugin', 'marketplace', 'add', CLAUDE_MARKETPLACE] },
    { kind: 'run', cmd: ['claude', 'plugin', 'install', CLAUDE_PLUGIN_ID] },
  ];
}

export function removeOpencodePlugin(opts = {}) {
  const { dryRun = false, force = false, ...rest } = opts;
  const status = opencodeStatus(rest);
  if (!status.exists) return { ...status, action: 'absent' };
  if (status.foreign && !force) {
    return { ...status, action: 'refused', reason: 'not a dotmd-generated file' };
  }
  if (!dryRun) rmSync(status.path, { force: true });
  return { ...status, action: 'removed' };
}
